import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 250010;
    static long[] fact = new long[MAX_SIZE];
    static long[] invFact = new long[MAX_SIZE];
    static long[][] dpStates = new long[30][MAX_SIZE];
    static int[] bitsCount = new int[MAX_SIZE];
    static long totalCount, maxLimit, modVal;

    static long choose(int n, int r) {
        return fact[n] * invFact[n - r] % modVal * invFact[r] % modVal;
    }

    static void add_value(long[] x, int index, long y) {
        x[index] += y;
        if (x[index] >= modVal) x[index] -= modVal;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        totalCount = sc.nextLong();
        maxLimit = sc.nextLong();
        modVal = sc.nextLong();

        fact[0] = 1;
        invFact[0] = 1;
        fact[1] = 1;
        invFact[1] = 1;

        for (int i = 2; i <= totalCount; i++) {
            long q = modVal / i;
            long r = modVal - i * q;
            fact[i] = fact[i - 1] * i % modVal;
            invFact[i] = modVal - (q * invFact[(int) r] % modVal);
        }

        for (int i = 2; i <= totalCount; i++) {
            invFact[i] = invFact[i - 1] * invFact[i] % modVal;
        }

        long result = 1;
        for (int i = 1; i <= totalCount; i++) {
            result = result * maxLimit % modVal;
        }

        for (int i = 1; i <= totalCount; i++) {
            bitsCount[i] = bitsCount[i >> 1] + (i & 1);
        }

        if ((totalCount & 1) == 1) {
            System.out.println(result);
            return;
        }

        dpStates[0][0] = 1;
        int maxBits = Math.min(bitsCount[(int) totalCount], (int) maxLimit);
        for (int i = 0; i < maxBits; i++) {
            for (int j = 0; j < totalCount; j++) {
                if (dpStates[i][j] == 0) continue;
                int mask = (int) (totalCount ^ j);
                for (int k = mask; k > j; k = (k - 1) & mask) {
                    int r = k | j;
                    add_value(dpStates[i], r, dpStates[i][j] * invFact[k] % modVal);
                }
            }
        }

        for (int i = 1; i <= maxLimit; i++) {
            long temp = dpStates[i][(int) totalCount] * fact[(int) maxLimit] % modVal
                    * invFact[(int) (maxLimit - i)] % modVal * fact[(int) totalCount] % modVal;
            result -= temp;
        }

        result = (modVal + result % modVal) % modVal;
        System.out.println(result);
        sc.close();
    }
